 entry={'Id':eid,'SourceTerm':term,'CorpusBaselineSha256':BASE,'CreatedBy':'Codex f004 C1186-1195 sourceGroups author','WrittenUtc':NOW,'Senses':[sense]}; out=ROOT/'entries'/eid;out.mkdir(parents=True,exist_ok=True)
